<script setup lang="ts">import{Head,Link,router,useForm}from'@inertiajs/vue3';import DashboardLayout from '@/Layouts/DashboardLayout.vue';import type{Property,PropertyType,User}from'@/types';const props=defineProps<{property?:Property;types:PropertyType[];amenities:{id:number;name:string}[];realtors:User[]}>();const form=useForm({title:props.property?.title||'',slug:props.property?.slug||'',description:props.property?.description||'',property_type_id:props.property?.type?.id||'',realtor_id:props.property?.realtor?.id||'',operation:props.property?.operation||'sale',price:props.property?.price||'',address:props.property?.address||'',district:props.property?.district||'',rooms:props.property?.rooms||'',area:props.property?.area||'',floor:props.property?.floor||'',total_floors:props.property?.total_floors||'',status:props.property?.status||'draft',is_featured:props.property?.is_featured||false,amenities:props.property?.amenities?.map(a=>a.id)||[],images:[] as File[]});const submit=()=>{const opts={forceFormData:true};props.property?form.post(`/manage/properties/${props.property.slug}`,{...opts,_method:'patch'} as any):form.post('/manage/properties',opts)};const files=(e:Event)=>form.images=Array.from((e.target as HTMLInputElement).files||[]);const deleteImage=(id:number)=>router.delete(`/manage/properties/${props.property?.slug}/images/${id}`,{preserveScroll:true});</script>
<template><Head :title="property?'Редактирование объекта':'Новый объект'"/><DashboardLayout><div class="flex items-center gap-3"><Link href="/manage/properties" class="text-[#174c43]">← Назад</Link></div><h1 class="mt-4 text-4xl">{{property?'Редактирование':'Новый объект'}}</h1><form class="mt-8 grid gap-6" @submit.prevent="submit"><section class="card grid gap-5 p-7"><h2 class="text-2xl">Основная информация</h2><label><span class="label">Название</span><input v-model="form.title" class="field" required><span class="text-xs text-red-700">{{form.errors.title}}</span></label><label><span class="label">Описание</span><textarea v-model="form.description" class="field" rows="7" required/><span class="text-xs text-red-700">{{form.errors.description}}</span></label><div class="grid gap-4 md:grid-cols-3"><label><span class="label">Тип</span><select v-model="form.property_type_id" class="field" required><option value="" disabled>Выберите</option><option v-for="t in types" :value="t.id">{{t.name}}</option></select></label><label><span class="label">Сделка</span><select v-model="form.operation" class="field"><option value="sale">Продажа</option><option value="rent">Аренда</option></select></label><label><span class="label">Цена, $</span><input v-model="form.price" class="field" type="number" min="1" required></label></div></section><section class="card grid gap-5 p-7"><h2 class="text-2xl">Расположение и параметры</h2><div class="grid gap-4 md:grid-cols-2"><label><span class="label">Адрес</span><input v-model="form.address" class="field" required></label><label><span class="label">Район</span><input v-model="form.district" class="field" required></label></div><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><label><span class="label">Комнаты</span><input v-model="form.rooms" class="field" type="number"></label><label><span class="label">Площадь, м²</span><input v-model="form.area" class="field" type="number" step="0.1" required></label><label><span class="label">Этаж</span><input v-model="form.floor" class="field" type="number"></label><label><span class="label">Этажей всего</span><input v-model="form.total_floors" class="field" type="number"></label></div></section><section class="card p-7"><h2 class="text-2xl">Удобства</h2><div class="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><label v-for="a in amenities" class="flex items-center gap-2 text-sm"><input v-model="form.amenities" type="checkbox" :value="a.id" class="rounded border-stone-300 text-[#174c43]">{{a.name}}</label></div></section><section class="card grid gap-5 p-7"><h2 class="text-2xl">Публикация и фотографии</h2><div class="grid gap-4 md:grid-cols-2"><label><span class="label">Статус</span><select v-model="form.status" class="field"><option value="draft">Черновик</option><option value="moderation">На модерации</option><option value="published">Опубликован</option><option value="sold">Продан</option><option value="rented">Сдан</option></select></label><label v-if="realtors.length"><span class="label">Ответственный риелтор</span><select v-model="form.realtor_id" class="field"><option value="">Не назначен</option><option v-for="r in realtors" :value="r.id">{{r.name}}</option></select></label></div><label class="flex items-center gap-2"><input v-model="form.is_featured" type="checkbox">Рекомендуемый объект</label><label><span class="label">Добавить фотографии (до 10)</span><input class="field" type="file" multiple accept="image/*" @change="files"></label><div v-if="property?.images?.length" class="grid grid-cols-2 gap-3 md:grid-cols-4"><div v-for="img in property.images" class="relative"><img :src="img.path" :alt="img.alt" class="h-32 w-full rounded-lg object-cover"><button type="button" class="absolute right-2 top-2 rounded bg-white px-2 py-1 text-xs font-bold text-red-700" @click="deleteImage(img.id)">Удалить</button></div></div></section><div class="flex gap-3"><button class="btn btn-primary" :disabled="form.processing">{{property?'Сохранить':'Создать объект'}}</button><Link href="/manage/properties" class="btn btn-light">Отмена</Link></div></form></DashboardLayout></template>
